<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Data Lakehouse Architecture — Medallion Pipeline &amp; Governance</title>
<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@300;400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
:root {
  --bg: #0d1117;
  --surface-0: #161b22;
  --surface-1: #1e2530;
  --surface-2: #252d3a;
  --border: rgba(100,140,180,0.15);
  --border-bright: rgba(100,160,220,0.3);
  --text: #e6edf3;
  --text-dim: #8b949e;
  --text-faint: #4a5568;

  --c-source:      #1d6a40;
  --c-source-bg:   rgba(29,106,64,0.18);
  --c-source-glow: rgba(52,168,100,0.25);
  --c-ingest:      #b45309;
  --c-ingest-bg:   rgba(180,83,9,0.18);
  --c-bronze:      #92400e;
  --c-bronze-bg:   rgba(180,100,20,0.2);
  --c-bronze-text: #f59e0b;
  --c-silver:      #1e5f8a;
  --c-silver-bg:   rgba(30,95,138,0.2);
  --c-silver-text: #60b4e0;
  --c-gold:        #7c5c10;
  --c-gold-bg:     rgba(212,167,58,0.2);
  --c-gold-text:   #d4a73a;
  --c-consume:     #4a1d6e;
  --c-consume-bg:  rgba(99,60,150,0.2);
  --c-consume-text:#c084fc;
  --c-gov:         #7f1d1d;
  --c-gov-bg:      rgba(220,60,60,0.15);
  --c-gov-text:    #f87171;

  --streaming-color: #22c55e;
  --batch-color:     #f59e0b;
  --cdc-color:       #60b4e0;
  --query-color:     #c084fc;

  --font-body: 'IBM Plex Sans', system-ui, sans-serif;
  --font-mono: 'IBM Plex Mono', 'Courier New', monospace;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  background: var(--bg);
  background-image:
    radial-gradient(ellipse 80% 40% at 50% 0%, rgba(30,95,138,0.08) 0%, transparent 60%),
    linear-gradient(180deg, rgba(30,50,80,0.15) 0%, transparent 100%),
    repeating-linear-gradient(0deg, transparent, transparent 39px, rgba(100,140,180,0.04) 39px, rgba(100,140,180,0.04) 40px),
    repeating-linear-gradient(90deg, transparent, transparent 39px, rgba(100,140,180,0.04) 39px, rgba(100,140,180,0.04) 40px);
  color: var(--text);
  font-family: var(--font-body);
  min-height: 100vh;
  padding: 0 0 60px;
}

/* ─── HEADER ─── */
.page-header {
  padding: 32px 40px 24px;
  border-bottom: 1px solid var(--border);
  background: rgba(22,27,34,0.9);
  position: sticky;
  top: 0;
  z-index: 100;
  backdrop-filter: blur(8px);
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
}
.page-header h1 {
  font-family: var(--font-mono);
  font-size: 18px;
  font-weight: 500;
  color: var(--c-silver-text);
  letter-spacing: 0.5px;
  line-height: 1.3;
}
.page-header h1 span {
  display: block;
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 400;
  color: var(--text-dim);
  letter-spacing: 1.5px;
  text-transform: uppercase;
  margin-bottom: 4px;
}
.header-stats {
  display: flex;
  gap: 28px;
  flex-shrink: 0;
}
.hstat {
  text-align: right;
}
.hstat-val {
  font-family: var(--font-mono);
  font-size: 22px;
  font-weight: 600;
  color: var(--c-gold-text);
  line-height: 1;
}
.hstat-label {
  font-size: 10px;
  color: var(--text-faint);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-top: 3px;
}

/* ─── MAIN LAYOUT ─── */
.main-canvas {
  padding: 32px 40px;
}

/* ─── SECTION LABEL ─── */
.section-label {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 2px;
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
}
.section-label::before {
  content: '';
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
}
.label-source::before      { background: #34a864; }
.label-ingest::before      { background: var(--batch-color); }
.label-bronze::before      { background: var(--c-bronze-text); }
.label-silver::before      { background: var(--c-silver-text); }
.label-gold::before         { background: var(--c-gold-text); }
.label-consume::before     { background: var(--c-consume-text); }
.label-gov::before          { background: var(--c-gov-text); }

/* ─── PIPELINE GRID ─── */
.pipeline {
  display: grid;
  grid-template-columns: 200px 160px 200px 200px 180px 200px;
  grid-template-rows: auto;
  gap: 0 0;
  position: relative;
  align-items: start;
}

/* ─── LAYER COLUMN ─── */
.layer-col {
  padding: 0 10px;
  border-right: 1px solid var(--border);
  min-width: 0;
}
.layer-col:last-child { border-right: none; }
.layer-col:first-child { padding-left: 0; }

/* ─── NODE CARDS ─── */
.node-card {
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 8px 10px;
  margin-bottom: 6px;
  font-size: 11px;
  line-height: 1.4;
  position: relative;
  transition: border-color 0.2s;
}
.node-card:hover { border-color: var(--border-bright); }

.node-name {
  font-weight: 500;
  color: var(--text);
  font-size: 11px;
}
.node-meta {
  color: var(--text-dim);
  font-size: 10px;
  font-family: var(--font-mono);
  margin-top: 2px;
}
.node-vol {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 600;
  margin-top: 4px;
  display: flex;
  align-items: center;
  gap: 4px;
}
.vol-bar {
  height: 3px;
  border-radius: 2px;
  flex-shrink: 0;
}

/* source variants */
.nc-iot        { background: rgba(29,106,64,0.12);  border-color: rgba(52,168,100,0.3); }
.nc-enterprise { background: rgba(180,83,9,0.1);    border-color: rgba(220,120,30,0.25); }
.nc-logs       { background: rgba(30,95,138,0.1);   border-color: rgba(60,140,200,0.25); }
.nc-external   { background: rgba(110,70,180,0.1);  border-color: rgba(160,100,220,0.25); }
.nc-database   { background: rgba(80,80,80,0.1);    border-color: rgba(140,140,140,0.25); }
.nc-ingest     { background: var(--c-ingest-bg);    border-color: rgba(220,120,30,0.35); }
.nc-bronze     { background: var(--c-bronze-bg);    border-color: rgba(240,150,30,0.3); }
.nc-silver     { background: var(--c-silver-bg);    border-color: rgba(60,150,220,0.3); }
.nc-gold       { background: var(--c-gold-bg);      border-color: rgba(212,167,58,0.4); }
.nc-consume    { background: var(--c-consume-bg);   border-color: rgba(180,100,250,0.3); }

/* volume colors */
.vol-iot      { color: #34a864; }
.vol-ent      { color: #f59e0b; }
.vol-logs     { color: #60b4e0; }
.vol-ext      { color: #a78bfa; }
.vol-db       { color: #94a3b8; }
.vol-ingest   { color: #fb923c; }
.vol-bronze   { color: var(--c-bronze-text); }
.vol-silver   { color: var(--c-silver-text); }
.vol-gold     { color: var(--c-gold-text); }

/* ─── FLOW ARROWS (SVG overlay) ─── */
.pipeline-wrap { position: relative; }
.flow-svg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 5;
  overflow: visible;
}

/* ─── GOVERNANCE PANEL ─── */
.gov-panel {
  background: var(--c-gov-bg);
  border: 1px solid rgba(220,60,60,0.25);
  border-radius: 8px;
  padding: 20px 24px;
  margin-top: 28px;
}
.gov-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 12px;
  margin-top: 16px;
}
.gov-card {
  background: rgba(127,29,29,0.15);
  border: 1px solid rgba(220,60,60,0.2);
  border-radius: 6px;
  padding: 10px 12px;
  font-size: 10.5px;
}
.gov-layer {
  font-family: var(--font-mono);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--c-gov-text);
  margin-bottom: 4px;
}
.gov-type {
  font-weight: 600;
  color: var(--text);
  font-size: 11px;
  line-height: 1.3;
}
.gov-tool {
  color: var(--text-dim);
  font-size: 10px;
  margin-top: 2px;
}
.gov-badge {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 8.5px;
  padding: 1px 5px;
  border-radius: 3px;
  margin-top: 5px;
}
.badge-auto     { background: rgba(34,197,94,0.2);  color: #86efac; }
.badge-policy   { background: rgba(96,180,224,0.2); color: var(--c-silver-text); }
.badge-manual   { background: rgba(245,158,11,0.2); color: var(--c-bronze-text); }
.badge-sched    { background: rgba(168,85,247,0.2); color: #d8b4fe; }

/* ─── TRANSFORMATION SUMMARY ─── */
.transform-panel {
  background: var(--surface-1);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 20px 24px;
  margin-top: 20px;
}
.transform-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 16px;
  margin-top: 16px;
}
.transform-col {
  border-radius: 6px;
  padding: 14px;
  border: 1px solid var(--border);
}
.transform-col.bronze-col { background: var(--c-bronze-bg); border-color: rgba(240,150,30,0.25); }
.transform-col.silver-col { background: var(--c-silver-bg); border-color: rgba(60,150,220,0.25); }
.transform-col.gold-col   { background: var(--c-gold-bg);   border-color: rgba(212,167,58,0.3); }
.transform-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}
.transform-title {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 600;
}
.transform-count-total {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-dim);
}
.transform-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 10.5px;
  padding: 4px 0;
  border-bottom: 1px solid rgba(255,255,255,0.05);
}
.transform-row:last-child { border-bottom: none; }
.t-name { color: var(--text); flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.t-count { font-family: var(--font-mono); font-size: 11px; font-weight: 600; margin-left: 8px; flex-shrink: 0; }
.t-complexity {
  display: inline-block;
  width: 8px; height: 8px;
  border-radius: 2px;
  margin-left: 6px;
  flex-shrink: 0;
}
.cx-low    { background: rgba(134,239,172,0.5); }
.cx-medium { background: rgba(251,191,36,0.5); }
.cx-high   { background: rgba(248,113,113,0.5); }

/* ─── LEGEND ─── */
.legend-strip {
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
  align-items: center;
  margin-top: 24px;
  padding: 14px 20px;
  background: var(--surface-1);
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 10.5px;
}
.legend-group {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}
.legend-group-label {
  font-family: var(--font-mono);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--text-faint);
  margin-right: 4px;
}
.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-dim);
  white-space: nowrap;
}
.legend-line {
  width: 24px;
  height: 2px;
  border-radius: 1px;
}
.legend-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.legend-sep {
  width: 1px;
  height: 20px;
  background: var(--border);
}

/* ─── CONSUMPTION FANOUT ─── */
.consumption-note {
  font-size: 10px;
  color: var(--text-dim);
  font-family: var(--font-mono);
  text-align: center;
  margin-top: 4px;
}
.consume-badge {
  font-size: 9px;
  font-family: var(--font-mono);
  padding: 2px 5px;
  border-radius: 3px;
  margin-top: 3px;
  display: inline-block;
}
.cb-bi  { background: rgba(212,167,58,0.2);  color: var(--c-gold-text); }
.cb-ml  { background: rgba(60,150,220,0.2);  color: var(--c-silver-text); }
.cb-api { background: rgba(180,100,250,0.2); color: var(--c-consume-text); }
.cb-retl{ background: rgba(34,197,94,0.2);   color: #86efac; }

/* ─── ANIMATIONS ─── */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}
.layer-col { animation: fadeUp 0.4s ease both; }
.layer-col:nth-child(1) { animation-delay: 0.05s; }
.layer-col:nth-child(2) { animation-delay: 0.1s; }
.layer-col:nth-child(3) { animation-delay: 0.15s; }
.layer-col:nth-child(4) { animation-delay: 0.2s; }
.layer-col:nth-child(5) { animation-delay: 0.25s; }
.layer-col:nth-child(6) { animation-delay: 0.3s; }

.gov-panel  { animation: fadeUp 0.4s ease 0.35s both; }
.transform-panel { animation: fadeUp 0.4s ease 0.42s both; }
.legend-strip    { animation: fadeUp 0.4s ease 0.48s both; }

@media (prefers-reduced-motion: reduce) {
  .layer-col, .gov-panel, .transform-panel, .legend-strip {
    animation: none;
  }
}
</style>
</head>
<body>

<header class="page-header">
  <div>
    <h1><span>Modern Data Lakehouse</span>End-to-End Pipeline — Medallion Architecture &amp; Governance Overlay</h1>
  </div>
  <div class="header-stats">
    <div class="hstat">
